import 'package:blockchain_utils/blockchain_utils.dart';
import 'package:blockchain_utils/crypto/crypto/monero/api/src/api.dart';
import 'package:blockchain_utils/crypto/crypto/monero/api/src/dart.dart';
import 'package:test/test.dart';

import '../../utils.dart';

// Bulletproofs+ M1 proof generated by monero_dart
// (amounts [0], deterministic RNG) — cross-implementation vector.
const String _m1Blob =
    '018a12f7c06d03f0b0c959de875b49c5c59adf5242887b3914dd1535a9e7ac1bcfd'
    '2a2b9a23a6b54965ca965beef61d049aa0ac27abb183cf0e1d01ae5398233c1'
    '501edc182c82a61f22134da01d93833cd13047e53ffd04c72d0e326c33fe8e3c8'
    '11978c77ece2c5df444474d2667f35a7917b2862854c8554e3b37f7ac335569748'
    'bb703e1d8810b510f27be94bf7aac726b7b0f36fc103b1da07446b950c90322693a'
    'f0b24aeb5e6adbdd627f494354dfa1863f070e1cbb7f311aefbbc0ff0fdbc3d3783'
    'e038622b809dccb1d416286d6df89ea53216f6e942d3f77d487980a06cacf90eeeb'
    '522efd7534cdf72091f8a0120e1346fb7201d869a369222a5e14b500721a8b46625'
    '3cb43d11b20e2d39738eef69af0c76fc2d44e000e1bee11fbbc95147ad9c4a4fdf7d'
    '0aca8f3cf42ed84521f683c57b5a7b8e03ed6df29f03732ed66a94b04da28f1feb8b'
    '42dd94620ad28c588886f0f415a3d2330213800db9f4edd75907e5c9ee0848e3f2fe'
    '7970f71859d1b53a09812573bdb869be6e0c66ee292143f8ec4eebd444ef445e2096'
    'b34ec157bc5c90e8f5eb484b554c1637b559a9323401b551f26e7ca6897606dd4219'
    'ccf11afeea95750ceed9380f64d2fa3a5a39f615c0b1385f6483ecbaac10cc196f19'
    '64b226d47b389b69aeb663696686a29ad50398a9c04331495dfe83165d4f577259c9'
    '6cf2d4a540523ed74b58b397a13e053326bb16ce9b0a33212234721fe96e966b66a7'
    'a7d3161355143b18d32cb118c0e2f7d4a231d20c03cc550d387ad61fc5847fd229cb'
    'de67afaa55f46a4e1d937971313fbcd3e5aea6b74fe60406c35b2b43b596900d787b'
    '0459ec32b40';

List<int> _hex(String s) => BytesUtils.fromHexString(s);

void moneroTest() {
  // Backend-dependent vectors run only on the native backend; the pure-Dart
  // backend exposes DartMoneroApi stubs (covered below on every backend).
  final native = blockchainUtils.api.monero is! DartMoneroApi;
  group('monero/bulletproofs-plus', () {
    test('dart backend throws BuError', () {
      const api = DartMoneroApi();
      expect(() => api.bpPlusVerify([]), throwsA(isA<BuError>()));
      expect(
        () => api.bpPlusProveAmounts(
          amounts: [BigInt.zero],
          gamma: [List<int>.filled(32, 1)],
          seed: List<int>.filled(32, 2),
        ),
        throwsA(isA<BuError>()),
      );
      expect(
        () => api.unlockBatch(accounts: [], outputs: []),
        throwsA(isA<BuError>()),
      );
    });

    test(
      'verify monero_dart M1 vector',
      () {
        final proof = MoneroBpPlusProof.fromBlob(_hex(_m1Blob));
        expect(proof.v.length, 1);
        expect(proof.l.length, 6);
        expect(blockchainUtils.api.monero.bpPlusVerify([proof]), true);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test(
      'prove amounts roundtrip (M=1)',
      () {
        final gamma = List<int>.filled(32, 0)..[0] = 7;
        final seed = List<int>.filled(32, 9);
        final proof = blockchainUtils.api.monero.bpPlusProveAmounts(
          amounts: [BigInt.zero],
          gamma: [gamma],
          seed: seed,
        );
        expect(proof.v.length, 1);
        expect(blockchainUtils.api.monero.bpPlusVerify([proof]), true);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test(
      'prove amounts roundtrip (M=4)',
      () {
        final g1 = List<int>.filled(32, 0)..[0] = 7;
        final g2 = List<int>.filled(32, 0)..[0] = 5;
        final seed = List<int>.filled(32, 11);
        final proof = blockchainUtils.api.monero.bpPlusProveAmounts(
          amounts: [BigInt.zero, BigInt.from(5), BigInt.from(123456789)],
          gamma: [g1, g2, g1],
          seed: seed,
        );
        expect(proof.v.length, 3);
        expect(proof.l.length, 8);
        expect(blockchainUtils.api.monero.bpPlusVerify([proof]), true);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test(
      'prove scalars roundtrip',
      () {
        final sv = List<int>.filled(32, 0)..[0] = 42;
        final gamma = List<int>.filled(32, 0)..[0] = 3;
        final seed = List<int>.filled(32, 13);
        final proof = blockchainUtils.api.monero.bpPlusProveScalars(
          sv: [sv],
          gamma: [gamma],
          seed: seed,
        );
        expect(blockchainUtils.api.monero.bpPlusVerify([proof]), true);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test(
      'tampered proof verifies false',
      () {
        final proof = MoneroBpPlusProof.fromBlob(_hex(_m1Blob));
        final bad = List<int>.from(proof.d1)..[0] ^= 1;
        final tampered = MoneroBpPlusProof(
          v: proof.v,
          a: proof.a,
          a1: proof.a1,
          b: proof.b,
          r1: proof.r1,
          s1: proof.s1,
          d1: bad,
          l: proof.l,
          r: proof.r,
        );
        expect(blockchainUtils.api.monero.bpPlusVerify([tampered]), false);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test('malformed input throws', () {
      expect(
        () => MoneroBpPlusProof.fromBlob([1, 2, 3]),
        throwsArgumentException,
      );
    });

    test(
      'unlockBatch rejects bad input before native call',
      () {
        final account = BuMoneroScanAccount(
          viewSecret: List<int>.filled(32, 1),
          spendPubs: [BuBytes(List<int>.filled(32, 2))],
        );
        final output = BuMoneroScanOutput(
          outKey: List<int>.filled(32, 3),
          txPub: List<int>.filled(32, 4),
        );
        expect(
          () => blockchainUtils.api.monero
              .unlockBatch(accounts: [], outputs: [output]),
          throwsArgumentException,
        );
        expect(
          () => blockchainUtils.api.monero
              .unlockBatch(accounts: [account], outputs: []),
          throwsArgumentException,
        );
        expect(
          () => blockchainUtils.api.monero.unlockBatch(
            accounts: [
              BuMoneroScanAccount(
                viewSecret: List<int>.filled(31, 1),
                spendPubs: [BuBytes(List<int>.filled(32, 2))],
              ),
            ],
            outputs: [output],
          ),
          throwsArgumentException,
        );
      },
      skip: native ? false : 'requires Rust (native) backend',
    );

    test(
      'unlockBatch synthetic scan crosses FFI with no match',
      () {
        final matches = blockchainUtils.api.monero.unlockBatch(
          accounts: [
            BuMoneroScanAccount(
              viewSecret: List<int>.filled(32, 1),
              spendPubs: [BuBytes(List<int>.filled(32, 2))],
            ),
          ],
          outputs: [
            BuMoneroScanOutput(
              outKey: List<int>.filled(32, 3),
              txPub: List<int>.filled(32, 4),
            ),
          ],
        );
        expect(matches, isEmpty);
      },
      skip: native ? false : 'requires Rust (native) backend',
    );
  });
}

void main() {
  BlockchainUtilsTestApi.runTest(moneroTest, 'Monero');
}
